  "sol.eyebrow": "The solution",
  "sol.title": "1 system instead of 10+ separate tools.",
  "sol.sub": "Symbiosis brings together everything a business needs to grow - client database, sales pipeline, proposals, projects, finance, notifications and AI. No API keys, no extra AI subscriptions, no needless complexity. Everything works together from day one.",
  "sol.core": "Symbiosis",
